export class Authentication {
    constructor() {
    }
    async getAuthInstance() {
        if (!this.authInstance) {
            if (typeof window === 'undefined') {
                const { ZCAuth } = await import('@zcatalyst/auth-admin');
                this.authInstance = new ZCAuth();
            }
            else {
                throw new Error('Browser environment detected. Please use the browser variant of @zcatalyst/auth');
            }
        }
        return this.authInstance;
    }
    async init(options, config) {
        const instance = await this.getAuthInstance();
        return instance.init(options, config);
    }
    async getApp(name) {
        const instance = await this.getAuthInstance();
        return instance.app(name);
    }
}
export { USER_STATUS, UserManagementAdmin as UserManagement } from './user-management.js';
export const zcAuth = new Authentication();
